def flags(a,b):
    s=a+b;r=s&255;c=int(s>255)
    sa=a-256 if a>127 else a;sb=b-256 if b>127 else b;sr=sa+sb
    v=int(not -128<=sr<=127);h=int((a&15)+(b&15)>15)
    return r,c,v,h
assert flags(200,100)==(44,1,0,0) and flags(100,100)==(200,0,1,0) and flags(8,9)==(17,0,0,1)
assert 200+100==300==256+44 and 100+100-256==-56 and 0x11+6==0x17 and 8+9==17
assert f'{200:08b}'=='11001000' and f'{100:08b}'=='01100100' and f'{44:08b}'=='00101100'
assert 21+23+22+24==90 and 90>>1==45 and 45>>1==22 and 90>>2==22 and 90/4==22.5 and f'{90:07b}'=='1011010' and f'{22:05b}'=='10110'
