def modes_fig(keys):
    o=TL(6,14,'команда','t-s mu')+TL(130,14,'дерек қайда','t-s mu')+T(324,14,'жад*','t-s mu')
    spec={'imm':('LOAD A,#7',),'reg':('LOAD A,R1',),'dir':('LOAD A,200',),'ind':('LOAD A,@300',)}
    for i,k in enumerate(keys):
        cy=40+i*44;o+=R(6,cy-14,100,28,'bxa')+T(56,cy+4,spec[k][0],'t-s t-b')
        if k=='imm':o+=TL(116,cy+4,'дерек командада: A = 7','t-s');n='0'
        elif k=='reg':o+=A(106,cy,128,cy)+R(130,cy-14,84,28,'bx')+T(172,cy+4,'R1 = 7','t-s');n='0'
        elif k=='dir':o+=A(106,cy,128,cy)+R(130,cy-14,84,28,'bx')+T(172,cy+4,'жад[200] = 7','t-s');n='1'
        else:o+=A(106,cy,128,cy)+R(130,cy-14,84,28,'bx')+T(172,cy+4,'жад[300]=200','t-s')+A(214,cy,232,cy)+R(232,cy-14,84,28,'bxa')+T(274,cy+4,'жад[200]=7','t-s');n='2'
        o+=T(324,cy+4,n,'t-s t-b ac')
    o+=TL(6,40+len(keys)*44-4,'* команданы алудан басқа жад оқулары','t-s mu')
    return o
